@startuml

class Project {
  + startDate : date
  + endDate : date
}

class WorkProduct {
  + description : string
  + percentComplete : float
  + Validate()
}

class Requirement extends WorkProduct {
  + Validate()
  + Publish()
}

class System extends WorkProduct {
  + Validate()
  + Deploy()
}

class ProjectManager {
  + InitiateProject()
  + TerminateProject()
}

class Team {}

ProjectManager -- Project : Manage
ProjectManager -- Team : Lead
Team -- Project : Execute
Project -- Requirement : Input
Project -- System : Output

@enduml

